"use client";

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { getCategories } from "@/services/categories";
import { getSuppliers } from "@/services/suppliers";

export default function ProductForm({
  onSubmit,
  defaultValues = {},
}: {
  onSubmit: (data: any) => void;
  defaultValues?: any;
}) {
  const [name, setName] = useState(defaultValues.name || "");
  const [sku, setSku] = useState(defaultValues.sku || "");
  const [price, setPrice] = useState(defaultValues.price || "");
  const [stock, setStock] = useState(defaultValues.stock || 0);
  const [categoryId, setCategoryId] = useState(defaultValues.categoryId || "");
  const [supplierId, setSupplierId] = useState(defaultValues.supplierId || "");
  const [description, setDescription] = useState(defaultValues.description || "");

  const { data: categories } = useQuery({ queryKey: ["categories"], queryFn: getCategories });
  const { data: suppliers } = useQuery({ queryKey: ["suppliers"], queryFn: getSuppliers });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    onSubmit({
      name,
      sku,
      price: Number(price),
      stock: Number(stock),
      categoryId,
      supplierId: supplierId || null,
      description,
    });
  };

  return (
    <form
      onSubmit={handleSubmit}
      className="space-y-5 max-w-xl bg-white p-6 rounded-xl shadow-sm border"
    >
      <div className="grid grid-cols-2 gap-4">
        <div className="col-span-2">
          <label className="block text-sm font-medium text-gray-700 mb-1">Product Name</label>
          <input
            placeholder="e.g. Wireless Mouse"
            className="border rounded-lg p-2 w-full"
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">SKU</label>
          <input
            placeholder="SKU-123"
            className="border rounded-lg p-2 w-full"
            value={sku}
            onChange={(e) => setSku(e.target.value)}
            required
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Price (₹)</label>
          <input
            placeholder="0.00"
            type="number"
            step="0.01"
            className="border rounded-lg p-2 w-full"
            value={price}
            onChange={(e) => setPrice(e.target.value)}
            required
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Initial Stock</label>
          <input
            placeholder="0"
            type="number"
            className="border rounded-lg p-2 w-full"
            value={stock}
            onChange={(e) => setStock(e.target.value)}
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Category</label>
          <select
            className="border rounded-lg p-2 w-full"
            value={categoryId}
            onChange={(e) => setCategoryId(e.target.value)}
            required
          >
            <option value="">Select Category</option>
            {categories?.map((c: any) => (
              <option key={c.id} value={c.id}>{c.name}</option>
            ))}
          </select>
        </div>

        <div className="col-span-2">
          <label className="block text-sm font-medium text-gray-700 mb-1">Supplier (Optional)</label>
          <select
            className="border rounded-lg p-2 w-full"
            value={supplierId}
            onChange={(e) => setSupplierId(e.target.value)}
          >
            <option value="">Select Supplier</option>
            {suppliers?.map((s: any) => (
              <option key={s.id} value={s.id}>{s.name}</option>
            ))}
          </select>
        </div>

        <div className="col-span-2">
          <label className="block text-sm font-medium text-gray-700 mb-1">Description</label>
          <textarea
            placeholder="Product details..."
            className="border rounded-lg p-2 w-full h-24"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
          />
        </div>
      </div>

      <button className="w-full bg-teal-600 text-white px-4 py-3 rounded-lg font-bold hover:bg-teal-700 transition-colors">
        Save Product
      </button>
    </form>
  );
}